import{_ as p,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"易纂言","description":"易纂言 - 易纂言","frontmatter":{"title":"易纂言","description":"易纂言 - 易纂言"},"headers":[],"relativePath":"zh/classics/zuanyan/001.md","filePath":"zh/classics/zuanyan/001.md"}'),n={name:"zh/classics/zuanyan/001.md"};function r(c,a,_,i,o,l){return t(),e("div",null,[...a[0]||(a[0]=[s('<h1 id="易纂言" tabindex="-1">易纂言 <a class="header-anchor" href="#易纂言" aria-label="Permalink to “易纂言”">​</a></h1><p>钦定四库全书经部一</p><p>易类提要</p><p>臣 等谨案：易纂言十二卷，元吴澄撰。字幼清，号草庐，崇仁人。宋咸淳末举进士不第，入元以荐擢翰林应奉文字，官至翰林学士，卒谥文正。事迹具元史本传。是书用吕祖谦古易本。经文每卦先列卦变主爻，每爻先列变爻，次列象占十翼亦各分章数。其训解各附句下，音释、考证则经附每卦之末，传附每章之末。间有文义相因，即附辨于句下者，偶一二见，非通例也。澄于诸经好臆为点窜，惟此书所改，则有根据者为多。如师卦「丈人吉」改「大人吉」，据崔憬所引子夏傅本；比卦「比之匪人」下增「凶」字，据王肃本；小畜卦「舆说辐」改「舆说輹」，据许慎说文。「尚德载」改「尚得载」，据京房、虞翻、子夏本。泰卦「包荒」改「包巟」，据说文及虞翻本。大畜卦「曰闲舆卫」改「日闲舆卫」，从郑元、虞翻、陆希声本；萃卦「萃亨」删「亨」字。从马融、郑元、虞翻、陆绩本。困卦「劓刖」改「臲卼」。据荀爽、王肃、陆绩本。鼎卦「其形渥」改「其刑剭」。据郑元本。比彖「比吉也」删「也」字。据王昭素本。贲彖补「刚柔交错」四字。据王弼注。震彖「惊远而慎迩也」下补「不丧匕鬯」四字。据王昭素所引徐氏本。渐彖「女归吉也」改「女归吉利贞」。据王肃本。坤象「履霜坚冰」改「初六履霜」。据魏志。坎象「樽酒簋贰」删「贰」字。据陆德明释文。 案：澄注明言旧本有「贰」字，陆氏释文无之，今世所行张弧、陆希声本皆同，是傅文已删去「贰」字。徐氏通志堂本乃劖补刊板，增入「贰」字，是顾湄等校正之时以不误为误也。谨附识于此。 繋辞上傅「繋辞焉而明吉凶」下补「悔吝」二字。据虞翻本。繋辞下傅「何以守位曰仁」改「何以守位曰人」。据王肃本。「耒耨之利」改「耒耨之地」。据王昭素本。「以济不通」下删「致远以利天下」六字。据陆德明释文序卦传；「故受之以履」下补「履者礼也」四字，据韩康伯本。皆据引古义，具有源流，不比师心变乱。其余亦多依傍胡瑗、程子、朱子诸说。澄所自改正者，不过数条而已。惟以繋辞傅中说上下经十六卦十八爻之文，定为错简，移置于文言傅中，则悍然臆断，不可以为训矣。然其解释经义，词简理明，融贯旧闻，亦颇赅洽，在元人说易诸家，固终为巨擘焉。乾隆四十六年九月恭校上。</p><p>总纂官 臣 纪昀、 臣 陆锡熊、 臣 孙士毅，总校官 臣 陆费墀。钦定四库全书易纂言卷首元吴澄撰</p><p>易</p><p>易者，阴易相变易也。上古包羲氏，见天地万物之性情形体，一易一阴而已，于是作一奇画以象阳，作一耦画以象阴。见一阳一阴之互相易也，故自一奇一耦相易而为四象八卦，极于六十四卦，是为卦画之象。又作揲蓍之法，教民以卦而占吉凶，自一变而极于十有八变，是为蓍数之变。卦象、蓍变皆以阴阳相易，故名之曰「易」。其时未有「易」字也，后之造字者，合「日」「月」二文而为「易」字。日，阳精昱乎画；月，阴精昱乎夜。日往则月来，月往则日来，阴阳相易而成昼夜，故「易」从「日」从「月」。字书乂谓「易」字象蜥蜴之形，而假借为「变易」之「易」，盖不然也。礼记曰：「昔者圣人达阴阳天地之情，立以为易。」 □□</p><p>羲皇画卦之时，先作此一画。一者为奇，阳之象也；一者为耦，阴之象也。阳浑合无间，故「一」；阴受衡即开，故「二」。后人名之为两仪。系辞传曰：「易有太极，是生两仪。」邵子谓：一分为二。朱子谓：一奇一耦为一画者，二是也。其画一，其位二，其奇耦之数三。 □□□□，</p><p>奇耦一画之上再加一奇一耦，以象阴阳之有老少。「奇」上加「奇」者，阳之纯，故象老阳；奇上加耦者，阴杂于阳中，故象少阴；耦上加奇者，阳杂于阴中，故象少阳。耦上加耦者，阴之纯，故象老阴。后人名之为「四象」。系辞传曰：「两仪生四象。」邵子谓「二分为四」。朱子谓两仪八，各生奇耦，为二画者，四是也。其画二，其位四，其积画其奇耦之数十二。盖一画加一为二，其位则倍二为四也。 ☰☱☲☳☴☵☶☷ 二画之上又各加一奇一耦，奇奇之上加一奇，象天，而名「乾」。奇奇之上加一耦，象泽，而名「兑」。奇耦之上加一奇，象日象火，而名「离」。奇耦之上加一耦，象雷，而名「震」。耦奇之上加一奇，象风，而名「巽」。耦奇之上加一耦，象月象水，而名「坎」。耦耦之上加一奇，象山，而名「艮」。耦耦之上加一耦，象地，而名「坤」。乾一、兑二、离三、震四、巽五、坎六、艮七、坤八，总名之曰「八卦」。然当时未有乾、兑、离、震、巽、坎、艮、坤八字及卦字也。即此各卦三画之象，而名为「乾」，名为「兑」，名为「离」，名为「震」，名为「巽」，名为「坎」，名为「艮」，名为「坤」也。天、地、山、泽、日月、水火、雷风，亦有其名，而未有其字。系辞传曰：「四象生八卦，</p><p>八卦成列，象在其中矣。」邵子谓：四分为八。朱子谓：四象各生奇耦，为三画者八是也。其画三，其位八，其积画二十四，其奇耦之数三十六。盖二画加一为三，其位则倍四为八也。画至三而卦有八，为卦之小成，三才之象具矣。故定为此图。直竖则乾上坤下，离左坎右，震左后，兑左前，巽右前，艮右后。平布则乾南坤北，离东坎西，震东北，兑东南，巽西南，艮西北。系辞传曰：「天尊地卑，乾坤定矣。」说卦传曰：「天地定位，山泽通气，雷风相薄，水火不相射。」谓此图也。邵子曰：太极既分，两仪立矣。阳下交于阴，阴上交于阳，四象生矣。阳交于阴，阴交于阳，而生天之四象；刚交于柔，柔交于刚，而生地之四象。于是八卦成矣。乾以分之，坤以翕之，震以长之，巽以消之。长则分，分则消，消则翕也。乾坤，定位也。震、巽，一交也，兑、离、坎、艮，再交也。震，阳少而阴尚多也，巽，阴少而阳尚多也。兑、离，阳浸多也，坎、艮，阴浸多也。乾坤之名位不可易也，坎、离，名可易而位不可易也，震、巽，位可易而名不可易也，兑、艮，名与位皆可易也。离在天而当夜，故阳中有阴也；坎在地而当昼，故阴中有阳也。震始交阴而阳生，巽始消阳而阴生。兑，阳长也；艮，阴长也。震、兑，在天之阴也，巽、艮，在地之阳也。故震、兑上阴而下阳，巽艮上阳而下阴。天以始生言之，故阴上而阳下，交泰之义也；地以既成言之，故阳上而阴下，尊卑之位也。顺数之，乾一、兑二、离三、震四、巽五、坎六、艮七、坤八；逆数之，震一、离兑二、乾三、巽四、坎艮五、坤六也。乾坤定上下之位，离坎列左右之门，天地之所阖辟，日月之所出入，是以春夏秋冬，晦朔弦望，画夜长短、行度盈缩，莫不由乎此矣。乾坤纵而六子衡，易之本也。 □□□□□□□□□□□□□□□□， 三画之上又各加一奇一耦，邵子谓八分为十六，朱子谓八卦各生奇耦，为四画者十六。两仪之上加八卦，八卦之上加两仪是也。其画四，其位十六，其积画六十四，其奇耦之数九十六，盖三画加一为四，而其位则倍八为十六也。 □□□□□□□□□□□䷲□□□□□□□□□□□□□□□□□□□□， 四画之上又各加一奇一耦，邵子谓十六分为三十二，朱子谓四画各生奇耦，为五画者三十二。四象之上加八卦，八卦之上加四象是也。其画五，其位三十二，其积画一百六十，其奇耦之数二百四十，盖四画加一为五，其位则倍十六为三十二也。 ䷉䷪䷍䷡䷈䷄䷙䷊䷉䷹䷥䷵䷼䷻䷨䷒䷌䷰䷝䷶䷤䷾䷕䷣䷘䷐䷔䷲䷩䷂䷚䷗䷫䷛䷱䷟䷸䷭䷑䷭䷅䷮䷿䷧䷺䷜䷃䷆䷠䷞䷷䷽䷴䷦䷳䷎䷋䷬䷢䷏䷓䷇䷖䷁ 五画之上又各加一奇一耦，邵子谓三十二分为六十四，朱子谓五画各生奇耦，为六画者六十四。蔡氏谓，八卦重为六十四卦，一卦之上各有八卦是也。其画六，其位六十四，其积画三百八十四，其奇耦之数五百七十六。盖五画加一为六，其位则倍三十二为六十四也。邵子曰：一变而二，二变而四，三变而八卦成矣。四变而十有六，五变而三十有二，六变而六十四卦备矣。画至六而卦有六十四，为卦之大成。兼三才而两之，万物万事悉备矣。故又为此图，以圆函方。圆者，象天周地外，方者，象地在天中。说卦传曰：「八卦相错，数往者顺，知来者逆。」谓此图也。邵子曰：八卦相交错而成六十四卦。数往者，若顺天而行，是左旋也，皆已生之卦也。「知来」者，若逆天而行，是右行也，皆未生之卦也。无极之前，阴含阳也；有象之后，阳分阴也。阴为阳之母，阳为阴之父。故母孕长男而为复，父生长女而为姤。是以阳起于复，阴起于姤也。夫易根于乾坤，而生于姤复，盖刚交柔而为复，柔交刚而为姤，自兹而无穷矣。复至乾，凡百有十二阳；姤至坤，凡八十阳；姤至坤，凡百有十二阴；复至乾，凡八十阴。阳在阴中，阳逆行；阴在阳中，阴逆行。阳在阳中，阴在阴中，则皆顺行。此真至理，案图可见之矣。邵氏曰：「此图圆布者，乾尽午中，坤尽子中，离尽卯中，坎尽酉中。阳生于子中，极于午中；阴生于午中，极于子中。其阳在南，其阴在北。方布者，乾始于西北，坤尽于东南，其阳在北，其阴在南。二者阴阳对待之数。图于外者为阳，方于中者为阴。圆者动而为天，方者静而为地也。」</p><p>右羲皇之易。昔在羲皇，始画八卦，因而重之为六十四。当是时，易有图而无书也。后圣因之作连山，作归藏，作周易，虽一本诸羲皇之图，而其取用盖各不同焉。三易既亡其二，而周易独存，世儒诵习，知有周易而已。羲皇卦图鲜或传授，而沦落于方伎家，虽其说具见于夫子之系辞、说卦，而读者莫之察也。至宋邵子始得而发挥之，于是人乃知有羲皇之易，而学易者不断自文王、周公始也。今于易之一经，首揭此图，冠于经端，以为羲皇之易，而后以三易继之，盖欲使夫学者知易之本源，不至寻流逐末而昧其所自云尔。 以上凡八图。其八卦定位、六十四卦方圆凡二图，邵子得之于李之才挺之，李得之穆修伯长，穆得之希夷先生陈抟图南。盖羲皇八卦、重卦既成之后，作此二图也。儒者不传，而方伎家传之，以为修养火候之节。其一画、二画、三画、四画、五画、六画，凡六图，则朱子推而得之，载于易学启蒙。虽失其传授所自，然考夫子系辞传所言，及邵子观物外篇所推，则古有此图也必矣。盖羲皇未作八卦定位、重卦方圆二图之时，先有此图也。故今定此以为羲皇之易云。 易连山䷳ 艮下艮上。</p><p>此连山易之首卦也。以下六十三卦先后之次不可知。 右夏之易。周官：「大卜掌三易，一曰连山，二曰归藏，三曰周易。其经卦皆八，其别皆六十有四。」或曰：神农作连山，夏因之，以其首艮，故曰连山，今亡。归藏䷁ 坤下坤上。</p><p>此归藏易之首卦也。以下六十三卦先后之次不可知。 右商之易。子曰：「我欲观殷道，是故之宋，而不足征也，吾得坤乾焉。」说者以坤乾为归藏。或曰：黄帝作归藏，商因之，以其首坤，故曰归藏，今亡。 案，夏、商二易，盖因羲皇所画之卦而用之以占筮，卦序与先天自然之序不同，故连山首艮，归藏首坤。朱子易赞曰：「降帝而王，传夏历商，有占无文，民用弗彰。」以为二易无繇辞也。或曰，春秋左氏传所载繇辞与周易不同者，盖夏、商之易，则以为有繇辞矣，然今莫可考证。世俗所传归藏易，伪书也。 易纂言卷首。</p>',13)])])}const m=p(n,[["render",r]]);export{h as __pageData,m as default};
